deer_baby.code:
const brown = H.mat('#b5733a',{rough:0.9});
const cream = H.mat('#f1deb8',{rough:0.9});
const white = H.mat('#fff8e8',{rough:0.9});
const dark = H.mat('#2a1a10',{rough:0.6});
const black = H.mat('#0b0b0b',{rough:0.3});
const g = H.group('deer');
g.add(H.sphere(1,brown,{pos:[0,0.64,0],scale:[0.26,0.27,0.55],name:'body'}));
g.add(H.sphere(1,cream,{pos:[0,0.5,0.02],scale:[0.2,0.18,0.45],name:'belly'}));
// neck + head
g.add(H.cyl(0.07,0.1,0.4,brown,{pos:[0,0.97,0.46],rot:[28,0,0],name:'neck'}));
g.add(H.sphere(1,brown,{pos:[0,1.18,0.66],scale:[0.11,0.12,0.17],name:'head'}));
g.add(H.sphere(1,cream,{pos:[0,1.12,0.78],scale:[0.07,0.06,0.09]}));
g.add(H.sphere(0.03,black,{pos:[0,1.13,0.86],name:'nose'}));
g.add(H.sphere(0.028,black,{pos:[0.075,1.22,0.74],name:'eye_r'}));
g.add(H.sphere(0.028,black,{pos:[-0.075,1.22,0.74],name:'eye_l'}));
g.add(H.sphere(1,brown,{pos:[0.12,1.34,0.6],scale:[0.05,0.13,0.03],rot:[0,0,-30],name:'ear_r'}));
g.add(H.sphere(1,brown,{pos:[-0.12,1.34,0.6],scale:[0.05,0.13,0.03],rot:[0,0,30],name:'ear_l'}));
// legs
const lp=[[0.13,0.36],[-0.13,0.36],[0.13,-0.4],[-0.13,-0.4]];
lp.forEach((p,i)=>{
  g.add(H.cyl(0.04,0.028,0.5,brown,{pos:[p[0],0.26,p[1]],name:'leg_'+i}));
  g.add(H.cyl(0.03,0.032,0.07,dark,{pos:[p[0],0.035,p[1]],name:'hoof_'+i}));
});
g.add(H.sphere(0.06,white,{pos:[0,0.82,-0.57],name:'tail'}));
// white spots (baby fawn)
const r=H.rng(11);
for(let i=0;i<16;i++){
  const x=(r()-0.5)*0.4, z=(r()-0.5)*0.9;
  const k=1-(x/0.26)*(x/0.26)-((z)/0.55)*((z)/0.55);
  if(k<0.15) continue;
  g.add(H.sphere(0.026,white,{pos:[x,0.64+0.27*Math.sqrt(k)+0.002,z],scale:[1,0.4,1]}));
}
return g;

bush_thorn.code:
const g = H.group('bush');
const r = H.rng(5);
const greens=['#2f5d2a','#3a6e30','#27502a','#46783a'].map(c=>H.mat(c,{rough:0.95}));
const twig = H.mat('#5a3d22',{rough:0.9});
for(let i=0;i<9;i++){
  const a=r()*Math.PI*2, d=r()*0.55;
  const s=0.38+r()*0.3;
  g.add(H.sphere(s,greens[i%4],{pos:[Math.cos(a)*d,s*0.8+r()*0.15,Math.sin(a)*d],scale:[1,0.85,1]}));
}
for(let i=0;i<7;i++){
  const a=r()*Math.PI*2;
  g.add(H.tube([[0,0.1,0],[Math.cos(a)*0.4,0.5+r()*0.3,Math.sin(a)*0.4],[Math.cos(a)*0.85,0.35+r()*0.4,Math.sin(a)*0.85]],0.018,twig));
}
return g;

golden_plant.code:
const g = H.group('golden_plant');
const soilMat = H.pbr('stone', {color: '#4a3525', roughness: 0.9});
const goldStem = H.mat('#eab308', {rough: 0.2, metal: 0.8, emissive: '#ca8a04', emissiveIntensity: 0.8});
const goldLeaf = H.mat('#fde047', {rough: 0.15, metal: 0.7, emissive: '#facc15', emissiveIntensity: 1.5});
const glowCore = H.emissive('#fef08a', 3.5);
const runeRing = H.emissive('#fbbf24', 2.2);

g.add(H.cyl(0.55, 0.7, 0.18, soilMat, {pos: [0, 0.09, 0], name: 'base'}));
g.add(H.torus(0.62, 0.03, runeRing, {pos: [0, 0.12, 0], rot: [90, 0, 0], name: 'magic_ring'}));

const stem = H.tube([[0, 0.15, 0], [0.05, 0.45, 0.03], [-0.04, 0.75, -0.02], [0, 1.05, 0]], 0.045, goldStem, {name: 'stem'});
g.add(stem);

for (let i = 0; i < 6; i++) {
  const ang = (i * 60) * Math.PI / 180;
  const h = 0.35 + (i % 3) * 0.2;
  const lx = Math.cos(ang) * 0.22;
  const lz = Math.sin(ang) * 0.22;
  const leaf = H.sphere(0.16, goldLeaf, {pos: [lx, h, lz], scale: [1.4, 0.35, 0.8], rot: [0, -i * 60, 25], name: 'leaf_' + i});
  g.add(leaf);
}

for (let i = 0; i < 8; i++) {
  const ang = (i * 45) * Math.PI / 180;
  const px = Math.cos(ang) * 0.18;
  const pz = Math.sin(ang) * 0.18;
  const petal = H.sphere(0.14, goldLeaf, {pos: [px, 1.08, pz], scale: [1.6, 0.4, 0.7], rot: [0, -i * 45, 35], name: 'petal_' + i});
  g.add(petal);
}

g.add(H.sphere(0.15, glowCore, {pos: [0, 1.15, 0], name: 'blossom_core'}));
return g;
